import { createHmac } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// `after()` throws outside a Next request scope. Capture the scheduled callback
// so the fire-and-forget path can be asserted deterministically.
const scheduled: Array<() => Promise<void> | void> = [];
vi.mock("next/server", () => ({
	after: (fn: () => Promise<void> | void) => {
		scheduled.push(fn);
	},
}));

import {
	deliverServerEvents,
	reportServerEvent,
	reportServerEvents,
} from "@/lib/analytics-server";

const SECRET = "test-secret";
const HQ = "https://api.example.test";

function headers(init: Record<string, string> = {}): Headers {
	return new Headers({
		"x-forwarded-for": "203.0.113.7, 10.0.0.1",
		"x-vercel-ip-country": "IL",
		"user-agent": "curl/8.7.1",
		...init,
	});
}

function hmacHex(value: string): string {
	return createHmac("sha256", SECRET).update(value).digest("hex");
}

let fetchMock: ReturnType<typeof vi.fn>;

beforeEach(() => {
	scheduled.length = 0;
	process.env.HQ_API_URL = HQ;
	process.env.ANALYTICS_HMAC_SECRET = SECRET;
	fetchMock = vi.fn(async () => new Response(null, { status: 204 }));
	vi.stubGlobal("fetch", fetchMock);
});

afterEach(() => {
	vi.unstubAllGlobals();
	// NOTE: assigning undefined would set the STRING "undefined"; delete is the
	// only way to actually unset an env var.
	delete process.env.HQ_API_URL;
	delete process.env.ANALYTICS_HMAC_SECRET;
});

describe("deliverServerEvents", () => {
	it("posts straight to HQ ingest, not through the same-origin /api/analytics hop", async () => {
		// The hop is what would collapse every server event onto one visitor_id.
		await deliverServerEvents(headers(), [
			{ name: "agent:api-request", path: "/llms.txt", properties: { a: 1 } },
		]);
		expect(fetchMock).toHaveBeenCalledTimes(1);
		expect(fetchMock.mock.calls[0][0]).toBe(`${HQ}/api/analytics/ingest`);
	});

	it("derives visitor_id from the ORIGINAL client IP, matching the edge handler", async () => {
		await deliverServerEvents(headers(), [
			{ name: "agent:api-request", path: "/llms.txt", properties: {} },
		]);
		const body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		// First entry of x-forwarded-for, HMAC-SHA256 with the shared secret.
		expect(body.visitor_id).toBe(hmacHex("203.0.113.7"));
		expect(body.country).toBe("IL");
		expect(body.user_agent).toBe("curl/8.7.1");
	});

	it("signs the exact enriched bytes with the edge handler's scheme", async () => {
		await deliverServerEvents(headers(), [
			{ name: "agent:not-found", path: "/.well-known/oauth", properties: {} },
		]);
		const init = fetchMock.mock.calls[0][1] as RequestInit & { body: string };
		const sent = (init.headers as Record<string, string>)[
			"X-Analytics-Signature"
		];
		expect(sent).toBe(`sha256=${hmacHex(init.body)}`);
	});

	it("keeps the envelope key order the signature is computed over", async () => {
		await deliverServerEvents(headers(), [
			{ name: "agent:api-request", path: "/openapi.json", properties: {} },
		]);
		const init = fetchMock.mock.calls[0][1] as { body: string };
		expect(Object.keys(JSON.parse(init.body))).toEqual([
			"project_id",
			"events",
			"visitor_id",
			"country",
			"user_agent",
		]);
	});

	it("puts path on the envelope, never duplicated into properties", async () => {
		await deliverServerEvents(headers(), [
			{
				name: "agent:api-request",
				path: "/api/md/foundations/overview",
				properties: { surface: "md" },
			},
		]);
		const body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		expect(body.events[0].path).toBe("/api/md/foundations/overview");
		expect(body.events[0].properties).toEqual({ surface: "md" });
		expect(body.project_id).toBe("orchestkit");
	});

	it("sends a whole batch in ONE ingest POST", async () => {
		await deliverServerEvents(headers(), [
			{ name: "agent:mcp-call", path: "/api/mcp", properties: { i: 1 } },
			{ name: "agent:mcp-call", path: "/api/mcp", properties: { i: 2 } },
		]);
		expect(fetchMock).toHaveBeenCalledTimes(1);
		const body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		expect(body.events).toHaveLength(2);
	});

	it("drops an over-long event name instead of letting it reject the batch", async () => {
		// The sink validates the whole payload at once: one name over 50 chars
		// returns a 500 and deletes every event in the batch, silently.
		await deliverServerEvents(headers(), [
			{ name: `agent:${"x".repeat(60)}`, path: "/x", properties: {} },
			{ name: "agent:mcp-call", path: "/api/mcp", properties: {} },
		]);
		const body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		expect(body.events).toHaveLength(1);
		expect(body.events[0].name).toBe("agent:mcp-call");
	});

	it("sends nothing at all when every name is invalid", async () => {
		await deliverServerEvents(headers(), [
			{ name: `agent:${"x".repeat(60)}`, path: "/x", properties: {} },
		]);
		expect(fetchMock).not.toHaveBeenCalled();
	});

	it("clamps path and user_agent to the sink's column widths", async () => {
		await deliverServerEvents(headers({ "user-agent": "u".repeat(900) }), [
			{ name: "agent:not-found", path: `/${"p".repeat(900)}`, properties: {} },
		]);
		const body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		expect(body.events[0].path).toHaveLength(500);
		expect(body.user_agent).toHaveLength(500);
	});

	it("no-ops when unconfigured, so local dev and CI never emit", async () => {
		delete process.env.ANALYTICS_HMAC_SECRET;
		await deliverServerEvents(headers(), [
			{ name: "agent:api-request", path: "/llms.txt", properties: {} },
		]);
		expect(fetchMock).not.toHaveBeenCalled();
	});

	it("swallows a dead sink rather than surfacing it to the request", async () => {
		fetchMock.mockRejectedValue(new Error("ECONNREFUSED"));
		await expect(
			deliverServerEvents(headers(), [
				{ name: "agent:api-request", path: "/llms.txt", properties: {} },
			]),
		).resolves.toBeUndefined();
	});

	it("falls back to x-real-ip, then to a constant, without throwing", async () => {
		await deliverServerEvents(new Headers({ "x-real-ip": "198.51.100.4" }), [
			{ name: "agent:api-request", path: "/llms.txt", properties: {} },
		]);
		let body = JSON.parse(fetchMock.mock.calls[0][1].body as string);
		expect(body.visitor_id).toBe(hmacHex("198.51.100.4"));
		expect(body.country).toBeNull();

		await deliverServerEvents(new Headers(), [
			{ name: "agent:api-request", path: "/llms.txt", properties: {} },
		]);
		body = JSON.parse(fetchMock.mock.calls[1][1].body as string);
		expect(body.visitor_id).toBe(hmacHex("unknown"));
	});
});

describe("reportServerEvents", () => {
	it("does not touch the network on the request path — it defers to after()", async () => {
		reportServerEvent(headers(), "agent:api-request", "/llms.txt", {
			surface: "llms",
		});
		expect(fetchMock).not.toHaveBeenCalled();
		expect(scheduled).toHaveLength(1);

		await scheduled[0]();
		expect(fetchMock).toHaveBeenCalledTimes(1);
	});

	it("schedules nothing for an empty batch", () => {
		reportServerEvents(headers(), []);
		expect(scheduled).toHaveLength(0);
	});
});
